import java.util.Scanner;

public class Main {
    static final int N = 500;
    static int md;
    static int[][] ch = new int[N + 1][N + 1];
    static Pair[] dp1 = new Pair[N + 1];
    static Pair[][][] dp2 = new Pair[2][N + 1][N + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void add_mod(long[] x, long y) {
        x[0] += y;
        if (x[0] >= md) x[0] -= md;
    }

    static long sum(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        md = sc.nextInt();

        for (int i = 0; i <= m; ++i) {
            ch[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                ch[i][j] = ch[i - 1][j];
                add_mod(new long[]{ch[i][j]}, ch[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= m; ++i) {
            dp1[i] = new Pair();
        }
        dp1[0].first = 1;

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= i; ++j) {
                long w = (dp1[j - 1].first * dp1[i - j].first) % md * ch[i - 1][j - 1] % md;
                long[] tempSecond = new long[]{dp1[i].second};
                add_mod(tempSecond, (sum(j - 1) + sum(i - j)) * w % md);
                add_mod(tempSecond, (dp1[j - 1].second * dp1[i - j].first) % md * (i + 1) % md * ch[i - 1][j - 1]);
                add_mod(tempSecond, (dp1[j - 1].first * dp1[i - j].second) % md * (i + 1) % md * ch[i - 1][j - 1]);
                dp1[i].second = tempSecond[0];

                long[] tempFirst = new long[]{dp1[i].first};
                add_mod(tempFirst, w * (i + 1) % md);
                dp1[i].first = tempFirst[0];
            }
        }

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                dp2[0][i][j] = new Pair();
                dp2[1][i][j] = new Pair();
            }
        }

        dp2[0][0][0].first = 1;
        dp2[1][0][0].first = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                for (int ln = 1; ln <= n - i; ++ln) {
                    // Update dp2[1][i + ln][j]
                    add_mod(new long[]{dp2[1][i + ln][j].first}, dp2[0][i][j].first);
                    add_mod(new long[]{dp2[1][i + ln][j].second}, dp2[0][i][j].second);

                    // Update dp2[0][i + ln][j + ln]
                    long val1 = (dp2[1][i][j].first * dp1[ln].first) % md * ch[j + ln][j] % md;
                    add_mod(new long[]{dp2[0][i + ln][j + ln].first}, val1);

                    long val2 = (dp2[1][i][j].first * dp1[ln].second) % md * ch[j + ln][j] % md;
                    add_mod(new long[]{dp2[0][i + ln][j + ln].second}, val2);

                    long val3 = (dp2[1][i][j].second * dp1[ln].first) % md * ch[j + ln][j] % md;
                    add_mod(new long[]{dp2[0][i + ln][j + ln].second}, val3);
                }
            }
        }

        long answer = dp2[0][n][m].second + dp2[1][n][m].second;
        answer %= md;
        System.out.println(answer);
        sc.close();
    }
}
